    // Lookahead logic: If the next item is large, avoid leaving a small gap now
    // that won't accommodate the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 30.0;
    }

    // Bias towards filling bins to capacity to reduce total_items impact.
    // We reward bins that end up with very small residuals (0-3).
    if post_residual <= 3 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Encourage Best-Fit behavior: Penalize large post_residuals.
    // Higher post_residual is generally bad, but we weight it against the mean.
    score += (post_residual as f64 - mean_residual).powi(2) * 0.1;

    // 2. Lookahead matching: If post_residual is close to next_item_size, reward it.
    // We prioritize bins that leave exactly enough (or slightly more) for the next item.
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        if diff >= 0 {
            // Reward perfect or near-perfect fits for the next item
            score -= (100.0 / (1.0 + diff as f64)) * 2.5;
        } else {
            // Penalize bins that cannot fit the next item if we are tight on space
            score += (diff.abs() as f64) * 0.8;
        }
    }

    // 3. New Bin Penalty: If the bin is brand new (residual == capacity), 
    // heavily penalize it unless no other bin can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0;
        }
    }

    // 4. Density Balancing: If we are near the end of the stream, 
    // be more aggressive about packing tightly (lower residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // 5. Fragmentation Avoidance: If this is the last bin that can fit the item,
    // give it a slight preference boost to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: proportional to how many bins are already open
        // and how much room is left in existing bins.
        score = 60.0 + (open_bins_count as f64 * 0.5) + (mean_residual * 0.2);
    } else {
        // Reward tight fits that leave little room for fragmentation
        // post_residual == 0 is the "Best Fit" ideal.
        score = post_residual as f64;

        // Lookahead penalty: if the next item is large and won't fit in this post_residual,
        // we penalize the placement to keep the bin open for a better match later.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 25.0 * (1.0 - progress);
        }

        // Penalty for creating 'dead zones' (small residuals that likely won't fit future items)
        if post_residual > 0 && post_residual < 15 {
            score += 15.0;
        }

        // If this is the last chance to fit the item in an existing bin, reduce penalty
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Dynamic scale adjustment based on the stage of the stream
    // As we approach the end, prioritize closing bins over opening new ones.
    if progress > 0.8 {
        if is_new_bin {
            score += 50.0;
        } else {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize opening new bins heavily early on, but allow flexibility as the stream progresses
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + 10.0
    } else {
        0.0
    };

    // Calculate how "tight" the fit is. 
    // We want to minimize post_residual (Best Fit), but penalize "near-misses" 
    // that leave a small, unusable gap (e.g., 1-9).
    let gap_penalty = if post_residual < 10 && post_residual > 0 {
        25.0 * (1.0 - (post_residual as f64 / 10.0))
    } else {
        0.0
    };

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than the next item, we penalize the current choice.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 0.5
    } else {
        0.0
    };

    // Coupling: Use mean_residual to balance the bin usage. 
    // If the current bin is significantly emptier than the average, favor filling it.
    let balance_factor = (bin_residual as f64 - mean_residual) * 0.2;

    // Base score is the post_residual (Best Fit logic).
    // We want the smallest remaining space, so lower score is better.
    let mut score = post_residual as f64 + gap_penalty + new_bin_penalty + lookahead_penalty + balance_factor;

    // If only one bin fits, prioritize it strongly to avoid unnecessary new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) logic: prioritize small post_residual.
    // Base score is already post_residual.

    // 2. Penalty for creating "orphaned" space (dead space that is unlikely to fit typical items).
    // If post_residual is in the range (0, 10), it is very difficult to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 3. Lookahead logic: if next_item_size is large, favor keeping space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= (bin_capacity - post_residual) as f64 * 0.2;
        } else {
            // Penalize bins that cannot accommodate the next item if they are otherwise "tight"
            score += 15.0;
        }
    }

    // 4. Harmonic coupling: favor bins that align with common item fractions (1/2, 1/3, 1/4 of capacity).
    // This reduces the number of bins with awkward residual sizes.
    let harmonic_penalty = (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // 5. New bin management:
    // Only open a new bin if the current fit is extremely inefficient (post_residual > 40)
    // or if the current bin count is low relative to the stream progress.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Forced to open
        } else {
            // Heavily penalize opening a new bin unnecessarily
            score = 100.0 + (post_residual as f64 * 2.0);
        }
    }

    // 6. Global state balancing:
    // If we have many open bins, prioritize closing them by penalizing high mean_residual.
    score += mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
