    }

    // 2. Lookahead Synergy: If next_item_size is known, favor bins that can accommodate it.
    // If post_residual is >= next_item_size, we reward the bin to keep the packing tight.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else {
            // Penalize if the current choice forces a new bin for the next item.
            score += (next_item_size as f64) * 0.5;
        }
    }

    // 3. New Bin Thresholding: Discourage opening a new bin (bin_residual == bin_capacity)
    // unless the fit in existing bins is objectively terrible (high post_residual).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is dynamic based on how many bins are already open.
        score += 45.0 + (open_bins_count as f64 * 0.2);
    }

    // 4. Fitting Constraint: If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
