    }

    // 6. Progressive tightening: As the stream nears the end, prioritize filling bins 
    // to capacity over keeping them "open" for future items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

