    // A new bin (bin_residual == 100) should be highly penalized unless fitting_bins_count == 0.
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin when existing options exist.
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 200.0; // Strong penalty to prioritize filling existing bins.
        } else {
            score -= 50.0; // Bonus to open a new bin if nothing else fits.
        }
    }

    // Lookahead: If next_item_size is large, favor bins that leave enough room for it.
    // If post_residual is slightly smaller than next_item_size, it's a "bad" fit (fragmentation).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual >= 10 {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64 * 0.8); // Reward "perfect" future fit.
        }
    }

    // Balance: Favor bins that stay near the mean residual to keep packing uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // Progression: As the stream nears the end, be more aggressive with packing (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    // Critical: If this is the last chance to fit the item (fitting_bins_count == 1),
    // and it's not a new bin, prioritize it heavily.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Non-linear penalty for slivers and large gaps; tuned to favor tight packing early.
    let mut score = post + (post / capacity).powf(6.8) * 190.0;

    // Lookahead: Anticipate the next item.
    if next_item_size > 0 {
        let n_size = next_item_size as f64;
        if post < n_size {
            // High penalty for creating a gap that cannot hold the next item.
            score += (n_size - post) * (22.0 - progress * 8.0);
        } else if post < (n_size + 15.0) {
            // Reward creating a "perfect fit" for the upcoming item.
            score -= 72.0 * (1.0 - progress * 0.1);
        }
    }

    if is_new_bin {
        // Dynamic barrier: Increase cost of new bins based on current packing density.
        let density_factor = (1.0 - (mean_residual / capacity)).clamp(0.0, 1.0);
        let dynamic_penalty = 125.0 + (progress * 45.0) + (open_bins_count as f64 * 7.5) - (density_factor * 30.0);
        score += dynamic_penalty;

        // If no other bin fits, the new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
    } else {
        // Residual variance constraint: Penalize divergence from the mean residual.
        score += (post - mean_residual).abs() * 0.55;

        // Forced-Fit Priority: heavily prioritize bins that reach near-capacity.
        if post < 3.0 {
            score -= 350.0;
        } else if fitting_bins_count <= 3 {
            score -= 180.0 / (fitting_bins_count as f64 + 1.0).sqrt();
        }

        // Efficiency bias: Reward near-perfect fits.
        if post < 14.0 {
            score -= (125.0 - (post * 7.5)) * (2.0 + progress * 0.5);
        }

        // Banking space: Favor bins that maintain lower-than-average residual to keep capacity open.
        if post < (mean_residual * 0.6) {
            score -= 65.0;
        }
    }

    // Global constraint: Aggressively discourage excessive bin count.
    if open_bins_count > 10 {
        score += post * 5.5;
    } else if open_bins_count < 4 && !is_new_bin {
        score -= 90.0;
    }

    // Entropy adjustment: If the mean residual is small, emphasize filling existing bins over new ones.
    if mean_residual < (capacity * 0.25) {
        score -= 40.0;
    }

    score
}

