    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize creating small, unusable gaps (1-9) which are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 - (post_residual as f64 * 4.5);
    }

    // 2. Lookahead logic: if next item is large, favor bins that can accommodate it
    if next_item_size > 0 {
        let fit_next = post_residual >= next_item_size;
        if !fit_next && next_item_size > 50 {
            score += 25.0; 
        } else if fit_next {
            score -= 10.0;
        }
    }

    // 3. Dynamic New Bin Threshold:
    // As the stream progresses, become increasingly conservative about opening new bins.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty for opening a new bin if an existing one works
            score += 60.0 + (progress * 40.0);
        } else {
            // If no fit, normalize score to be competitive
            score = 5.0;
        }
    } else {
        // 4. Global State Awareness:
        // Reward bins that keep the mean residual balanced to prevent fragmentation
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;

        // 5. Urgency: If this is the only fitting bin, prioritize it strongly
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Aggressive penalty for sliver generation: penalize post_residuals that are 
    // too small to fit common items but large enough to waste space.
    let mut score = post + (post / capacity).powi(6) * 150.0;

    // Lookahead: If current placement kills the ability to fit the next item, 
    // scale penalty by the remaining stream length to prioritize future-proofing.
    if next_item_size > 0 {
        let n_size = next_item_size as f64;
        if post < n_size {
            score += (n_size - post) * (15.0 - progress * 8.0);
        } else if post < (n_size + 15.0) {
            // Reward "Goldilocks" gaps: just enough space for the next item plus a small buffer.
            score -= 45.0 * (1.0 - progress * 0.2);
        }
    }

    if is_new_bin {
        // Dynamic threshold for opening new bins: scale penalty based on current mean density
        // to prevent premature bin creation when existing bins have sufficient capacity.
        let density_factor = (capacity - mean_residual) / capacity;
        score += 125.0 + (progress * 40.0) + (open_bins_count as f64 * 4.2) - (density_factor * 60.0);

        if fitting_bins_count == 0 {
            score -= 250.0; // Forced opening
        }
    } else {
        // Residual variance penalty: penalize bins that deviate significantly from the mean 
        // to encourage uniform packing density.
        score += (post - mean_residual).abs() * 0.6;

        // Forced-Fit Priority: prioritize bins that are nearing capacity.
        if post < 1.0 {
            score -= 400.0;
        } else if fitting_bins_count <= 3 {
            score -= 120.0 / (fitting_bins_count as f64);
        }

        // Efficiency bias: Reward near-perfect fits (post < 8) with intensity that scales with progress.
        if post < 8.0 {
            score -= (90.0 - (post * 7.0)) * (1.5 + progress);
        }

        // Banking space: Favor bins that maintain lower-than-average residual to preserve flexibility.
        if post < (mean_residual * 0.6) {
            score -= 35.0;
        }
    }

    // Global constraint: If bin count bloats, penalize larger post-residuals to force tighter packing.
    if open_bins_count > 10 {
        score += post * 5.5;
    } else if open_bins_count < 4 && !is_new_bin {
        score -= 60.0; // Keep existing bins active while count is low
    }

    // Entropy adjustment: If the mean residual is already small, intensify the focus on perfect fills.
    if mean_residual < (capacity * 0.25) {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space: we prefer smaller residuals (Best Fit behavior).
    let mut score = post_res;

    // Penalty for creating "dead zones": if the post_residual is small but not zero,
    // it prevents larger items from fitting. We penalize values in the range [1, 15].
    if post_residual > 0 && post_residual < 16 {
        score += (16.0 - post_res) * 2.5;
    }

    // Lookahead influence: If the next item is large, we want to preserve bins with 
    // higher residuals. We penalize bins that would leave too little space for the next item.
    if next_item_size > 0 {
        let next_fit_penalty = if post_residual < next_item_size { 20.0 } else { 0.0 };
        score += next_fit_penalty * (1.0 - progress);
    }

    // Dynamic Pressure: As the stream nears completion, we become more aggressive 
    // about packing tightly to avoid opening new bins.
    let tightness_factor = (mean_residual / bin_capacity as f64) * 10.0;
    score -= tightness_factor * progress;

    // New Bin Handling:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // that decays as the stream progresses, but is significantly higher if 
    // existing bins could still accommodate the item.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Global bin count scaling: slightly penalize opening too many bins early on.
    score += (open_bins_count as f64 * 0.5) * (1.0 - progress);

    score
}

