    // If post_residual is small, it's a tight fit (good).
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic:
    // Identify if the post_residual is near a "harmonic" multiple of the next_item_size.
    // We want to avoid leaving gaps that cannot fit common future items.
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        // If the remainder is very small, we have created a "dead zone" that is hard to fill.
        // Penalize residuals that are slightly larger than the next item.
        if post_residual > next_item_size && remainder < 10 {
            score += 25.0;
        }
        // Reward placements that leave exactly enough room for the next item.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless the current average residual is already very high (meaning bins are fragmented).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        }
        // If we are late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 4. Fragmentation Control:
    // If we have many open bins, penalize creating a new one or picking a bin that 
    // results in a post_residual significantly below the mean_residual.
    if post_residual < (mean_residual * 0.5) as u32 {
        score += 15.0;
    }

    // 5. Last Chance Heuristic:
    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

