    let post = post_residual as f64;
    let capacity = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Refined fitness: stronger penalty for "dead zones" (residuals too small to fit typical items).
    // Using a steeper power function to push residuals towards either 0 or near-capacity.
    let mut score = post + (post / capacity).powf(9.0) * 300.0;

    // Lookahead: Dynamic anticipation.
    if next_item_size > 0 {
        let n_size = next_item_size as f64;
        if post < n_size {
            // Penalize creating space that is just barely too small for the next expected item.
            score += (n_size - post) * (35.0 - progress * 12.0);
        } else if post < (n_size + 10.0) {
            // Reward "perfect fits" for the next item, scaling with progress to prioritize density.
            score -= 105.0 * (1.0 + progress * 0.3);
        }
    }

    if is_new_bin {
        // Dynamic barrier: Penalize new bins based on current system-wide slack.
        let density_factor = (mean_residual / capacity).clamp(0.0, 1.0);
        score += 150.0 + (progress * 90.0) + (open_bins_count as f64 * 12.0) + (density_factor * 85.0);

        // Only open new bins if we strictly have no choice or if current open bins are very full.
        if fitting_bins_count == 0 {
            score -= 420.0;
        }
    } else {
        // Variance control: Keep residuals close to the mean to maintain uniform density.
        score += (post - mean_residual).abs() * 0.95;

        // Forced-Fit Priority: If few bins can fit, prioritize keeping them to avoid opening new ones.
        if fitting_bins_count <= 2 {
            score -= 280.0 / (fitting_bins_count as f64 + 0.1);
        }

        // Efficiency bias: Reward near-perfect fills (post < 7) with high intensity.
        if post < 7.0 {
            score -= (180.0 - (post * 20.0)) * (2.2 + progress * 0.8);
        }

        // Strategic thinning: Favor bins with lower residuals to keep them "clean" for future items.
        if post < (mean_residual * 0.55) {
            score -= 75.0;
        }
    }

    // Global pressure: If open bins proliferate, force consolidation via penalty.
    if open_bins_count > 5 {
        score += (open_bins_count as f64 - 5.0) * 25.0;
    } else if open_bins_count < 3 && !is_new_bin {
        // Encourage using existing bins when availability is low.
        score -= 130.0;
    }

    // Entropy adjustment: If we are already packing efficiently, tighten criteria.
    if mean_residual < (capacity * 0.12) {
        score -= 60.0;
    }

    score
}

