    score += residual_diff * 0.1;

    // 5. Progression Scaling: As we approach the end of the stream, prioritize 
    // closing bins (lower post_residual) over keeping them open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 15.0;

    score
}

