    // 1. Best-Fit Penalty: Penalize large post_residuals (fragmentation)
    // We favor bins that leave the least space (Best-Fit principle).
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If post_residual perfectly accommodates next_item_size,
    // we heavily reward this bin to minimize future bin openings.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact fit or near-exact fit for the lookahead item
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 / (1.0 + diff)) * 2.5;
        } else {
            // Penalize if the bin becomes too small to hold the next item
            score += 15.0;
        }
    }

    // 3. Global Efficiency: If the current bin is empty (new bin candidate),
    // only choose it if the mean_residual is very high (meaning current bins are mostly full).
    if bin_residual == bin_capacity {
        if mean_residual < 20.0 {
            // Penalize opening a new bin if existing bins have plenty of space
            score += 50.0;
        } else {
            // Otherwise, keep the cost neutral to encourage opening if needed
            score += 10.0;
        }
    }

    // 4. Scarcity Constraint: If this is the last fitting bin, prioritize it
    // to avoid the penalty of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression Bias: As the stream nears the end, be more conservative with space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

