    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let capacity = bin_capacity as f64;

    let mut score = post;

    // Aggressive fragmentation penalty: 
    // Increased threshold to force cleaner utilization of remaining space.
    if post > 0.0 && post < 52.0 {
        score += (52.0 - post) * 24.0;
    }

    // Lookahead refinement: 
    // Penalize bins that would leave a post_residual too small for the next item, 
    // with higher sensitivity to stream progress.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next && post > 0.0 {
            let lookahead_penalty = (next - post) * 30.0 * (1.2 - progress).max(0.1);
            score += lookahead_penalty * (1.0 + (open_bins_count as f64 / 48.0));
        } else if post >= next && post < (next + 8.0) {
            // Reward "just enough" space to avoid creating tiny fragments
            score -= 22.0; 
        }
    }

    if bin_residual == bin_capacity {
        // New Bin Decision:
        // Increased resistance to opening new bins, scaling with current density.
        score += (mean_residual * 6.5) + (progress * 75.0);

        if fitting_bins_count > 0 {
            score += 340.0 * (1.0 - progress).powf(5.0) + (open_bins_count as f64 * 8.2);
        }
    } else {
        // Existing bin strategy:
        // Exponential reward for density, favoring bins that reach high utilization.
        let used = capacity - residual;
        score -= (used / capacity).powf(7.0) * 135.0;

        // Stricter penalty for "medium-empty" bins to force tighter packing.
        if residual > (capacity * 0.18) {
            score += (residual - (capacity * 0.12)) * 10.5;
        }
    }

    // Global density control:
    // Favors consolidation throughout, but allows more flexibility early in the stream.
    score += (open_bins_count as f64).powf(2.45) * (1.02 - (progress * 0.45));

    // Perfect fit priority:
    // Stronger incentive to zero-out bins.
    if post == 0.0 && bin_residual != bin_capacity {
        score -= 210.0;
    }

    // Entropy dampener: 
    // Encourages placing small items in moderately empty bins to preserve space for large items.
    if item_size < 28 {
        if residual > (capacity / 3.5) {
            score -= 48.0 * (1.0 - (residual / capacity)).powf(2.8);
        } else {
            score += 25.0; // Discourage clogging almost-full bins with small items
        }
    }

    score
}

